def get_missing_permissions(user, permissions):
    """
    Return a set of missing permissions for a given iterable of
    permission strings.

    1. Check missing permissions using `User.has_perm`-method
       allows us to use Django model permissions.
    2. Check missing permissions using Shuup admin custom
       permissions which are stored to configuration items
       per user group.

    :param user: User instance to check for permissions.
    :type user: django.contrib.auth.models.User
    :param permissions: Iterable of permission strings.
    :type permissions: Iterable[str]
    :return: Set of missing permission strings.
    :rtype: set[str]
    """
    if getattr(user, "is_superuser", False):
        return set()

    group_permissions = None

    if user:
        cache_key = "{}:{}".format(USER_PERMISSIONS_CACHE_NAMESPACE, user.pk)
        group_permissions = cache.get(cache_key)

        if group_permissions is None:
            group_permissions = get_permissions_from_groups(user.groups.values_list("pk", flat=True))
            cache.set(cache_key, group_permissions)

    if group_permissions:
        missing_permissions = set(p for p in set(permissions) if p not in group_permissions)
    else:
        missing_permissions = set(permissions)

    return missing_permissions
def apply_request_middleware(request, **attrs):
    """
    Apply all the `process_request` capable middleware configured
    into the given request.

    :param request: The request to massage.
    :type request: django.http.HttpRequest
    :param attrs: Additional attributes to set after massage.
    :type attrs: dict
    :return: The same request, massaged in-place.
    :rtype: django.http.HttpRequest
    """
    for middleware_path in get_middleware_classes():
        mw_class = import_string(middleware_path)
        current_language = get_language()

        try:
            mw_instance = mw_class()
        except MiddlewareNotUsed:
            continue

        for key, value in attrs.items():
            setattr(request, key, value)

        if hasattr(mw_instance, "process_request"):
            mw_instance.process_request(request)

        activate(current_language)

    assert request.shop

    if not attrs.get("skip_session", False):
        frm = inspect.stack()[1]
        mod = inspect.getmodule(frm[0])
        if mod.__name__.startswith("shuup_tests.admin"):
            shop_provider.set_shop(request, request.shop)

    return request
    def get_shop(cls, request, **kwargs):
        shop = getattr(request, "_cached_default_shop_provider_shop", None)
        if shop:
            return shop

        host = request.META.get("HTTP_HOST")
        if host:
            shop = get_shop_from_host(host)

        if not shop:
            shop = Shop.objects.first()


        setattr(request, "_cached_default_shop_provider_shop", shop)
        return shop
