def month_boundaries(months: int, tzstr: str) -> list[datetime]:
    tz = ZoneInfo(tzstr)
    result: list[datetime] = []

    now = timezone.now().astimezone(tz)
    y, m = now.year, now.month
    for x in range(0, months):
        result.insert(0, datetime(y, m, 1, tzinfo=tz))

        m -= 1
        if m == 0:
            m = 12
            y = y - 1

    return result
def put_object(code, n, data):
    key = "%s/%s" % (code, enc(n))
    retries = 10
    while True:
        try:
            client().put_object(settings.S3_BUCKET, key, BytesIO(data), len(data))
            break
        except S3Error as e:
            if e.code == "InternalError" and retries > 0:
                retries -= 1
                print("InternalError, retrying (retries=%d)..." % retries)
                continue

            raise e
