            for fileinfo in shared.get(str(folder), ""):
                if file == fileinfo[0]:
                    return True

        log.add_transfer("Failed to share file, since it wasn't found: %(virtual_name)s with real path %(path)s", {
            "virtual_name": virtualfilename,
            "path": realfilename
        })
        return False
